CATEGORIAS = {"entrega", "pagamento", "produto", "cancelamento", "outros"}

def valida(resp, texto_original):
    if resp.get("categoria") not in CATEGORIAS:
        raise ValueError("categoria invalida")
    idp = resp.get("id_pedido")
    if idp is not None and str(idp) not in texto_original:
        raise ValueError("id_pedido nao encontrado no texto")
    return resp
